(function () {
"use strict";

// --- LÓGICA DO CRONÔMETRO ---
let timerInterval = null;
let seconds = 0;

function startTimer() {
if (!timerInterval) {
timerInterval = setInterval(() => {
seconds++;
const m = Math.floor(seconds / 60).toString().padStart(2, '0');
const s = (seconds % 60).toString().padStart(2, '0');
document.getElementById('crono-timer').textContent = `${m}:${s}`;
}, 1000);
}
}

// --- ESTRUTURA DE DADOS DE DOWNES ---
const ITENS_DOWNES = [
{
id: "sibilancia", label: "1. Sibilancias", max: 3,
desc: "Auscultación de sibilancias respiratorias.",
opts: [
{ val: "", text: "Selecione..." },
{ val: 0, text: "No (0)" },
{ val: 1, text: "Final de la espiración (1)" },
{ val: 2, text: "Toda la espiración (2)" },
{ val: 3, text: "Inspiración + espiración (3)" }
]
},
{
id: "tiragem", label: "2. Retracciones", max: 3,
desc: "Uso de musculatura accesoria.",
opts: [
{ val: "", text: "Selecione..." },
{ val: 0, text: "No (0)" },
{ val: 1, text: "Subcostal + intercostal inferior (1)" },
{ val: 2, text: "'1' + supraclavicular + BAN (2)" },
{ val: 3, text: "'2' + intercostal superior + supraesternal (3)" }
]
},
{
id: "ventilacao", label: "3. Ventilación (entrada de aire)", max: 3,
desc: "Evaluación de la entrada de aire en los pulmones.",
opts: [
{ val: "", text: "Selecione..." },
{ val: 0, text: "Buena, simétrica (0)" },
{ val: 1, text: "Regular, simétrica (1)" },
{ val: 2, text: "Muy disminuida (2)" },
{ val: 3, text: "Tórax silencioso (ausencia de sibilancia) (3)" }
]
},
{
id: "cianose", label: "4. Cianosis", max: 1,
desc: "Coloración azulada de la piel/mucosas.",
opts: [
{ val: "", text: "Selecione..." },
{ val: 0, text: "No (0)" },
{ val: 1, text: "Sí (1)" }
]
},
{
id: "frequenciaRespiratoria", label: "5. Frecuencia Respiratoria", max: 3,
desc: "Incursiones por minuto (irpm).",
opts: [
{ val: "", text: "Selecione..." },
{ val: 0, text: "< 30 irpm (0)" },
{ val: 1, text: "31 - 45 irpm (1)" },
{ val: 2, text: "46 - 60 irpm (2)" },
{ val: 3, text: "> 60 irpm (3)" }
]
},
{
id: "frequenciaCardiaca", label: "6. Frecuencia Cardíaca", max: 1,
desc: "Latidos por minuto (bpm).",
opts: [
{ val: "", text: "Selecione..." },
{ val: 0, text: "< 120 bpm (0)" },
{ val: 1, text: "> 120 bpm (1)" }
]
}
];

// --- RENDERIZAÇÃO DOS CARDS ---
function renderizarItensDownes() {
const container = document.getElementById("downesForm");
container.innerHTML = "";

ITENS_DOWNES.forEach((item) => {
let optsHtml = "";
item.opts.forEach((op) => {
optsHtml += `<option value="${op.val}" ${op.val === "" ? "disabled selected" : ""}>${op.text}</option>`;
});

const div = document.createElement("div");
div.className = "item-card";
div.id = `card_${item.id}`;
div.innerHTML = `
<div class="flex items-center justify-between mb-2">
<label for="${item.id}" class="text-[13px] font-bold text-slate-800">${item.label}</label>
<span id="badge_${item.id}" class="item-badge">--/${item.max}</span>
</div>
<p class="text-[11px] text-slate-500 mb-3 leading-snug h-8">${item.desc}</p>
<select id="${item.id}" class="item-select">${optsHtml}</select>
<div class="mini-bar-wrap">
<div id="bar_${item.id}" class="mini-bar-fill" style="width: 0%;"></div>
</div>
`;
container.appendChild(div);

const el = document.getElementById(item.id);
el.addEventListener("change", () => {
document.getElementById(`card_${item.id}`).classList.remove("error");
document.getElementById("msgValidacaoErro").style.display = "none";
atualizarCardIndividual(item.id, item.max);
});

el.addEventListener('change', startTimer, {once: true});
el.addEventListener("wheel", function(e) { e.preventDefault(); this.blur(); });
});
}

// --- ATUALIZAR STATUS DE UM CARD ESPECÍFICO ---
function atualizarCardIndividual(id, max) {
const select = document.getElementById(id);
const valStr = select.value;
if (valStr === "") return;
const val = parseInt(valStr);
const pct = (val / max) * 100;

const badge = document.getElementById(`badge_${id}`);
const bar = document.getElementById(`bar_${id}`);

badge.textContent = `${val}/${max}`;
bar.style.width = `${pct}%`;

let cor = "#16a34a"; // 0 = Verde
if (val > 0) {
if (pct <= 33) cor = "#eab308"; // Amarelo
else if (pct <= 66) cor = "#f97316"; // Laranja
else cor = "#e11d48"; // Vermelho
}

bar.style.backgroundColor = cor;

// Badge também muda de cor conforme escore
badge.style.backgroundColor = cor === "transparent" ? "" : `${cor}15`;
badge.style.color = cor === "transparent" ? "" : cor;
badge.style.borderColor = cor === "transparent" ? "" : `${cor}30`;
atualizarBarraGlobal();
}

// --- BARRA FLUTUANTE GLOBAL E CONTADOR ---
function atualizarBarraGlobal() {
let preenchidos = 0;
ITENS_DOWNES.forEach((i) => {
if (document.getElementById(i.id).value !== "") preenchidos++;
});

const pctGlobal = (preenchidos / 6) * 100;
document.getElementById("progress-bar-global").style.width = `${pctGlobal}%`;
document.getElementById("contadorPreenchidos").textContent = `${preenchidos}/6`;
}

// --- LÓGICA DADOS DO PACIENTE (TOGGLE) ---
document.getElementById("btnToggleDados").addEventListener("click", function () {
const body = document.getElementById("dadosBody");
const chevron = document.getElementById("dadosChevron");
const subtitle = document.getElementById("dadosSubtitle");

if (body.classList.contains("open")) {
body.classList.remove("open");
chevron.style.transform = "rotate(0deg)";
subtitle.textContent = "Completar para el Expediente/Informe PDF";
this.style.background = "white";
} else {
body.classList.add("open");
chevron.style.transform = "rotate(180deg)";
subtitle.textContent = "Ocultar panel";
this.style.background = "#EFF6FF";
}
});
document.getElementById("pacData").value = new Date().toISOString().split("T")[0];

// --- CÁLCULO E RESULTADO ---
const resultadoSection = document.getElementById("resultado-section");

function calcular() {
let incompleto = false;
let somaTotal = 0;
let dominiosValores = [];
let diagnosticosKeywords = ["respiração", "gases", "ventilação", "oxigenação", "desobstrução"];
let primeiroErro = null;

ITENS_DOWNES.forEach((item) => {
const selectElement = document.getElementById(item.id);
const selectVal = selectElement.value;
if (selectVal === "") {
incompleto = true;
document.getElementById(`card_${item.id}`).classList.add("error");
if(!primeiroErro) primeiroErro = document.getElementById(`card_${item.id}`);
dominiosValores.push({ nome: item.label, obtido: 0, text: "No completado" });
} else {
document.getElementById(`card_${item.id}`).classList.remove("error");
const val = parseInt(selectVal);
somaTotal += val;
const textoSelect = selectElement.options[selectElement.selectedIndex].text.replace(/\s*\([^)]*\)$/, "");
dominiosValores.push({ nome: item.label, obtido: val, text: textoSelect });
}
});

if (incompleto) {
const msgErro = document.getElementById("msgValidacaoErro");
msgErro.style.display = "block";
if (primeiroErro) {
primeiroErro.scrollIntoView({ behavior: 'smooth', block: 'center' });
}
return;
}

document.getElementById("msgValidacaoErro").style.display = "none";
clearInterval(timerInterval);

// Determinar Classificação Downes
let classe = "", bgPill = "", recomendacao = "";
if (somaTotal === 0) {
classe = "Sin Malestar"; bgPill = "#16a34a"; // Verde
recomendacao = "Recién nacido en buenas condiciones respiratorias. Cuidados de rutina.";
} else if (somaTotal >= 1 && somaTotal <= 3) {
classe = "Malestar Leve"; bgPill = "#eab308"; // Amarelo
recomendacao = "Signos iniciales de dificultad respiratoria. Requiere observación continua y posible soporte leve.";
} else if (somaTotal >= 4 && somaTotal <= 7) {
classe = "Malestar Moderado"; bgPill = "#ea580c"; // Laranja
recomendacao = "Cuadro respiratorio comprometido. Necesaria intervención clínica (O2 o CPAP) para estabilización.";
} else {
classe = "Malestar Grave"; bgPill = "#e11d48"; // Vermelho
recomendacao = "Insuficiencia respiratoria inminente. Evaluar soporte ventilatorio avanzado e ingreso en UCI Neonatal.";
}

// Exibir no Hero Card
document.getElementById("scoreValor").textContent = somaTotal;
const pill = document.getElementById("statusPill");
pill.textContent = classe;
pill.style.backgroundColor = bgPill;

// Destacar card correspondente no Sidebar
const scpIds = ["scp-zero", "scp-leve", "scp-moderado", "scp-grave"];
scpIds.forEach(id => {
const el = document.getElementById(id);
if (el) {
el.style.transform = "scale(1)";
el.style.boxShadow = "";
el.classList.remove("scp-highlight");
}
});

let scpAlvo = null;
if (somaTotal === 0) scpAlvo = document.getElementById("scp-zero");
else if (somaTotal >= 1 && somaTotal <= 3) scpAlvo = document.getElementById("scp-leve");
else if (somaTotal >= 4 && somaTotal <= 7) scpAlvo = document.getElementById("scp-moderado");
else if (somaTotal >= 8) scpAlvo = document.getElementById("scp-grave");

if (scpAlvo) {
scpAlvo.style.transform = "scale(1.03)";
scpAlvo.style.boxShadow = "0 8px 25px rgba(0,0,0,0.25)";
scpAlvo.classList.add("scp-highlight");
}

document.getElementById("resultadoMensagem").innerHTML = `La puntuación total es de <strong>${somaTotal} puntos</strong> de un máximo de 14.<br><br><strong>Conducta:</strong> ${recomendacao}`;

// Gerar Tabela de Detalhamento
const tbody = document.getElementById("tabelaDominios");
tbody.innerHTML = "";
dominiosValores.forEach((dom) => {

let cor = "#16a34a"; // verde (0)
if (dom.obtido > 0) {
let itemDef = ITENS_DOWNES.find(i => i.label === dom.nome);
let pct = (dom.obtido / itemDef.max) * 100;
if (pct <= 33) cor = "#eab308"; // amarelo
else if (pct <= 66) cor = "#ea580c"; // laranja
else cor = "#e11d48"; // vermelho
}

const tr = document.createElement("tr");
tr.innerHTML = `
<td class="font-bold text-slate-700">${dom.nome.replace(/^\d+\.\s*/, "")}</td>
<td class="text-center font-black" style="color: ${cor}">${dom.obtido}</td>
<td class="text-center text-slate-400">${ITENS_DOWNES.find(i => i.label === dom.nome).max}</td>
<td>
<span class="text-[12px] font-bold px-3 py-1 rounded-lg inline-block" style="background-color: ${cor}10; color: ${cor}; border: 1px solid ${cor}30">${dom.text}</span>
</td>
`;
tbody.appendChild(tr);
});
document.getElementById("totalObtidoTd").textContent = somaTotal;
document.getElementById("totalObtidoTd").style.color = bgPill;

// Mostrar Seção
resultadoSection.classList.add("visible");
setTimeout(() => {
resultadoSection.scrollIntoView({ behavior: "smooth", block: "start" });
}, 100);

// Chamar NANDA
chamarNanda(diagnosticosKeywords);

window.__calcData = { soma: somaTotal, classe, dominios: dominiosValores };
}

async function chamarNanda(keywords) {
const lista = document.getElementById("lista-nanda");
lista.innerHTML = '<li class="text-sm text-slate-500 text-center py-4"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" class="fa-spin mr-2 inline-block" fill="currentColor" width="1em" height="1em" aria-hidden="true"><path d="M304 48a48 48 0 1 0 -96 0 48 48 0 1 0 96 0zm0 416a48 48 0 1 0 -96 0 48 48 0 1 0 96 0zM48 304a48 48 0 1 0 0-96 48 48 0 1 0 0 96zm464-48a48 48 0 1 0 -96 0 48 48 0 1 0 96 0zM142.9 437A48 48 0 1 0 75 369.1 48 48 0 1 0 142.9 437zm0-294.2A48 48 0 1 0 75 75a48 48 0 1 0 67.9 67.9zM369.1 437A48 48 0 1 0 437 369.1 48 48 0 1 0 369.1 437z"/></svg> Consultando base de datos NANDA-I...</li>';

try {
const response = await fetch("/banco_nanda.json");
if (!response.ok) throw new Error("Error fetch");
const banco = await response.json();

const pontuados = banco
.map((diag) => {
let matchScore = 0;
const texto = (diag.diagnostico + " " + diag.definicao).toLowerCase();
keywords.forEach((kw) => {
if (texto.includes(kw.toLowerCase())) matchScore++;
});
return { ...diag, matchScore };
})
.filter((d) => d.matchScore > 0);

pontuados.sort((a, b) => b.matchScore - a.matchScore);

// Dedup
const prefixosIgnorar = ["riesgo de", "disposición para", "síndrome de", "tendencia a", "disposición para", "riesgo de la"];
const temasUsados = new Set();
const topDiversos = [];

function extrairTema(titulo) {
let t = titulo.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
for (const p of prefixosIgnorar) {
if (t.startsWith(p)) { t = t.slice(p.length).trim(); break; }
}
const palavras = t.split(/\s+/).filter(w => w.length > 3 && !["para", "com", "sem", "como", "dos", "das", "que", "não", "nao", "melhorada", "melhorado", "prejudicada", "prejudicado", "adulto", "criança", "neonatal", "idoso", "lactente", "feminino", "masculino"].includes(w));
return palavras.slice(0, 4).join(" ");
}

for (const d of pontuados) {
const tema = extrairTema(d.diagnostico);
if (!temasUsados.has(tema) && !temasUsados.has(d.codigo)) {
temasUsados.add(tema);
temasUsados.add(d.codigo);
topDiversos.push(d);
}
if (topDiversos.length >= 6) break;
}

if (topDiversos.length > 0) {
lista.innerHTML = "";
topDiversos.forEach((d) => {
lista.innerHTML += `
<li class="nanda-item flex items-start gap-3">
<span class="bg-blue-100 text-blue-800 text-[10px] font-black px-2 py-1 rounded shadow-sm mt-0.5">${d.codigo}</span>
<div>
<h5 class="text-[13px] font-bold text-slate-800 leading-tight mb-1">${d.diagnostico}</h5>
<p class="text-[11px] text-slate-500 leading-snug m-0">${d.definicao}</p>
</div>
</li>
`;
});
} else {
lista.innerHTML = '<li class="text-xs text-slate-500 text-center py-4">Ningún diagnóstico crítico primario asociado a las selecciones actuales.</li>';
}
} catch (e) {
lista.innerHTML = '<li class="text-xs text-red-500 text-center py-4">Base de datos NANDA temporalmente no disponible.</li>';
}
}

function limpar() {
ITENS_DOWNES.forEach((item) => {
document.getElementById(item.id).value = "";
document.getElementById(`card_${item.id}`).classList.remove("error");

const badge = document.getElementById(`badge_${item.id}`);
const bar = document.getElementById(`bar_${item.id}`);
badge.textContent = `--/${item.max}`;
bar.style.width = `0%`;
bar.style.backgroundColor = "transparent";
});

document.getElementById("pacNome").value = "";
document.getElementById("pacIdade").value = "";
document.getElementById("pacSetor").value = "";
document.getElementById("msgValidacaoErro").style.display = "none";
atualizarBarraGlobal();

clearInterval(timerInterval);
timerInterval = null;
seconds = 0;
document.getElementById('crono-timer').textContent = "00:00";

const scpIds = ["scp-zero", "scp-leve", "scp-moderado", "scp-grave"];
scpIds.forEach(id => {
const el = document.getElementById(id);
if (el) {
el.style.transform = "scale(1)";
el.style.boxShadow = "";
el.classList.remove("scp-highlight");
}
});

resultadoSection.classList.remove("visible");
window.scrollTo({ top: 0, behavior: "smooth" });
window.__calcData = null;
}

// --- EXPORTAÇÃO (PDF e PRINT) ---
function getDadosImpressao() {
const cData = window.__calcData;
const dataVal = document.getElementById("pacData").value;
const dataFormatada = dataVal ? dataVal.split("-").reverse().join("/") : new Date().toLocaleDateString("pt-BR");
const tempo = document.getElementById("crono-timer").textContent;

return {
nome: document.getElementById("pacNome").value.trim(),
idade: document.getElementById("pacIdade").value.trim(),
setor: document.getElementById("pacSetor").value.trim(),
data: dataFormatada,
tempo: tempo,
soma: cData.soma,
classe: cData.classe,
dominios: cData.dominios
};
}

function gerarPDF() {
if (typeof window.jspdf === "undefined") {
const btn = document.getElementById("btnGerarPDF");
const origText = btn.innerHTML;
btn.innerHTML = "Cargando generador...";
btn.style.opacity = "0.7"; btn.style.pointerEvents = "none";
const s1 = document.createElement("script");
s1.src = "https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js";
document.body.appendChild(s1);
s1.onload = () => {
const s2 = document.createElement("script");
s2.src = "https://cdnjs.cloudflare.com/ajax/libs/jspdf-autotable/3.8.2/jspdf.plugin.autotable.min.js";
document.body.appendChild(s2);
s2.onload = () => {
btn.innerHTML = origText;
btn.style.opacity = "1"; btn.style.pointerEvents = "auto";
executarPDF();
};
};
return;
}
executarPDF();
}

function executarPDF() {
const { jsPDF } = window.jspdf;
const doc = new jsPDF({ orientation: "portrait", unit: "mm", format: "a4" });
const data = getDadosImpressao();

const navy = [26, 62, 116];
const slateLight = [241, 245, 249];
const W = 210,
marginL = 18,
marginR = 18,
usable = W - marginL - marginR;

// Cabeçalho
doc.setFillColor(...navy);
doc.rect(0, 0, W, 32, "F");
doc.setTextColor(255, 255, 255);
doc.setFont("helvetica", "bold");
doc.setFontSize(14);
doc.text("Escala de Wood-Downes", marginL, 13);
doc.setFontSize(9);
doc.setFont("helvetica", "normal");
doc.text("Evaluación del distrés respiratorio", marginL, 20);
doc.text("Fecha: " + data.data, W - marginR, 20, { align: "right" });

let y = 42;

// Identificação
if (data.nome || data.idade || data.setor) {
doc.setFillColor(...slateLight);
doc.roundedRect(marginL, y, usable, 8, 2, 2, "F");
doc.setTextColor(...navy);
doc.setFont("helvetica", "bold");
doc.setFontSize(9);
doc.text("IDENTIFICACIÓN DEL PACIENTE", marginL + 4, y + 5.5);
y += 12;

if (data.nome) {
doc.text("Nome/RN:", marginL, y);
doc.setFont("helvetica", "normal");
doc.setTextColor(30, 41, 59);
doc.text(data.nome, marginL + 20, y);
y += 6;
doc.setFont("helvetica", "bold");
doc.setTextColor(...navy);
}
if (data.idade) {
doc.text("Idade/IG:", marginL, y);
doc.setFont("helvetica", "normal");
doc.setTextColor(30, 41, 59);
doc.text(data.idade, marginL + 20, y);
y += 6;
doc.setFont("helvetica", "bold");
doc.setTextColor(...navy);
}
if (data.setor) {
doc.text("Setor/Leito:", marginL, y);
doc.setFont("helvetica", "normal");
doc.setTextColor(30, 41, 59);
doc.text(data.setor, marginL + 25, y);
y += 6;
}
y += 4;
}

// Pontuação Big
doc.setFillColor(...navy);
doc.roundedRect(marginL, y, usable, 22, 3, 3, "F");
doc.setTextColor(147, 197, 253);
doc.setFont("helvetica", "bold");
doc.setFontSize(8);
doc.text(`TIEMPO DE LA EVALUACIÓN: ${data.tempo}`, W / 2, y + 6, { align: "center" });
doc.setTextColor(255, 255, 255);
doc.setFontSize(26);
doc.text(String(data.soma) + " / 14", W / 2, y + 17, { align: "center" });
y += 28;

// Status Pill
let pillColor = [22, 163, 74]; // Verde
